import{_t as e,it as t,n,rt as r}from"./chunks/framework.GGfqtSwG.js";var i=JSON.parse(`{"title":"笔记是写给三个月后的自己的","description":"判断一条笔记值不值得记，只需要问一句：三个月后的我看得懂吗？三条原则和一次清理习惯。","frontmatter":{"title":"笔记是写给三个月后的自己的","date":"2026-08-14T00:00:00.000Z","description":"判断一条笔记值不值得记，只需要问一句：三个月后的我看得懂吗？三条原则和一次清理习惯。"},"headers":[],"relativePath":"posts/notes/notes-for-future-me.md","filePath":"posts/notes/notes-for-future-me.md"}`),a={name:`posts/notes/notes-for-future-me.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="笔记是写给三个月后的自己的" tabindex="-1">笔记是写给三个月后的自己的 <a class="header-anchor" href="#笔记是写给三个月后的自己的" aria-label="Permalink to “笔记是写给三个月后的自己的”">​</a></h1><p>大多数笔记写的时候很清楚，过一段时间再看就看不懂了——不是字迹问题， 而是当时脑子里有一整块上下文，笔记里只留下了结论。</p><h2 id="三条原则" tabindex="-1">三条原则 <a class="header-anchor" href="#三条原则" aria-label="Permalink to “三条原则”">​</a></h2><p><strong>记「为什么」，不只记「是什么」。</strong><code>maxRetries = 3</code> 是一条没用的笔记；<code>maxRetries = 3：对方接口高峰期偶发 503， 重试三次以内都能成功，超过就说明真的挂了</code> 才是有用的。</p><p><strong>记决策的边界条件。</strong> 「用 SQLite」这句话三个月后会引来一个问题：当时为什么不选 Postgres？ 把边界写下来——数据量、并发、部署环境——比结论本身值钱。</p><p><strong>写下否定过的选项。</strong> 试过、被排除的方案，往往才是重复劳动的重灾区。三次踩进同一个坑， 通常是因为第一次只记了「不行」，没记「为什么不行」。</p><h2 id="一次清理习惯" tabindex="-1">一次清理习惯 <a class="header-anchor" href="#一次清理习惯" aria-label="Permalink to “一次清理习惯”">​</a></h2><p>每季度挑一个下午，只做一件事：翻三个月前的笔记，把看不懂的地方补上。 不用重写，只在旁边加一句当时缺的上下文。</p><p>这个动作还有个副作用：<strong>它会立刻告诉你哪些笔记白记了</strong>。 连续几次都被跳过的那些，下次就不用记了。</p><div class="tip custom-block"><p class="custom-block-title">一条判据</p><p>如果一条笔记在三个月后需要你再花十分钟回忆才能用上， 那它其实没起到笔记的作用，只是一份当时的草稿。</p></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>笔记的目标不是「记下来」，而是「以后还能用上」。 把「三个月后看得懂吗」当成判据，很多笔记会自动变得更短，也更有用。</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};